package vn.svframe.fantasyhub.client;
import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;import com.google.gson.*;
class ShopViewTest {
 @Test void controlsAndPreviewStayInsideSmallAndScaledWindows(){for(int[] size:new int[][]{{320,180},{320,240},{426,240},{640,360},{854,480}}){var l=ShopView.layout(size[0],size[1]);for(var b:new ShopView.Box[]{l.tabs(),l.list(),l.preview(),l.details(),l.beast(),l.hunter(),l.footer()}){assertTrue(b.w()>0&&b.h()>0);assertTrue(b.x()>=l.panel().x()&&b.right()<=l.panel().right());assertTrue(b.y()>=l.panel().y()&&b.bottom()<=l.panel().bottom());}assertTrue(l.details().bottom()<l.beast().y());assertTrue(l.beast().bottom()<=l.hunter().y());assertTrue(l.hunter().bottom()<l.footer().y());assertTrue(l.list().right()<l.preview().x());}}
 @Test void threeTabsSeparateClassesBundlesAndAllItemCategories(){var c=JsonParser.parseString("{\"offers\":[{\"category\":\"classes\"},{\"category\":\"bundles\"},{\"category\":\"items\"},{\"category\":\"tickets\"},{\"category\":\"materials\"},{\"category\":\"titles\"},{\"category\":\"seasonal\"}]}").getAsJsonObject();assertEquals(1,ShopView.rows(c,ShopView.Tab.CLASS).size());assertEquals(1,ShopView.rows(c,ShopView.Tab.BUNDLE).size());assertEquals(5,ShopView.rows(c,ShopView.Tab.SHOP).size());}
 @Test void measuredEllipsisRespectsWideVietnameseAndSupplementaryCharacters(){var measure=(java.util.function.ToIntFunction<String>)s->s.codePoints().map(cp->cp>127?8:5).sum();String original="Kỵ sĩ huyền thoại 🛡 rất dài";String result=ShopView.fit(original,70,measure);assertTrue(measure.applyAsInt(result)<=70);assertTrue(result.endsWith("…"));assertFalse(Character.isHighSurrogate(result.charAt(result.length()-2)));assertEquals("Thor",ShopView.fit("Thor",70,measure));}
 @Test void formatsMoneyWithoutDroppingFractionalBalances(){assertEquals("196,000",ShopView.amount("196000"));assertEquals("1,234.5",ShopView.amount("1234.5000"));}
}
